function drawStar() {
  let numSpokes = 100;
  for (let i=0; i<numSpokes; i++) {
     let t0 = map(i, 0, numSpokes-1, 0, TWO_PI);
     let t1 = t0 + (TWO_PI/(2*numSpokes));
     arc(0, 0, 1000, 1000, t0, t1);
  }
}
